// Des: Run many accounts one at a time, rotating daily
// Flo: ids > rotate by day > per account: skip when halted > run (callback) > a Halted stop counts as a safety stop > two safety stops = the remaining accounts do not run > random gap before the next ; results with exit codes
// I/O: account ids + callback (caller) > Res per account; moves old prof/stat into acct/main (never deletes); the halt state lives in each account's own db
// ===================================================================
const std = @import("std"); const conf = @import("cf-conf-load.zig"); const data = @import("st-stat-data.zig"); const erro = @import("er-erro-type.zig");
const CF = .{ .sub = "acct", .stat = "stat", .prof = "prof", .dbfi = "za-stat.db", .corr = 2, .owner1 = "paused by owner", .owner2 = "stopped by owner" };
pub const Res = struct { id: []const u8, state: []const u8, code: u8 };
pub const Kind = enum { ok, owner, safety };
pub const Env = struct { aren: std.mem.Allocator, iozz: std.Io, cfg: conf.Conf, root: []const u8, ids: []const []const u8, now: i64, rng: *std.Random.DefaultPrng, ctx: ?*anyopaque, run: *const fn (ctx: ?*anyopaque, id: []const u8) anyerror!u8, say: *const fn (ctx: ?*anyopaque, msg: []const u8) void, nap: *const fn (iozz: std.Io, ms: u64) void = realNap, browser: bool = true };
pub fn realNap(iozz: std.Io, ms: u64) void { std.Io.sleep(iozz, .fromMilliseconds(@intCast(ms)), .awake) catch {}; }
pub fn applyScal(cfg: conf.Conf, scal: u32) conf.Conf { var out = cfg; if (scal >= 100) return out; const info = @typeInfo(conf.Conf).@"struct"; inline for (info.field_names, info.field_types) |fnm, fty| { if (fty == u32 and std.mem.startsWith(u8, fnm, "capz_")) { const base = @field(cfg, fnm); @field(out, fnm) = if (base == 0) 0 else @max(1, @as(u32, @intCast(@as(u64, base) * scal / 100))); } } return out; }
pub fn order(aren: std.mem.Allocator, ids: []const []const u8, now: i64) ![]const []const u8 { const out = try aren.alloc([]const u8, ids.len); if (ids.len == 0) return out; const off: usize = @intCast(@mod(@divFloor(now, 86400000), @as(i64, @intCast(ids.len)))); for (ids, 0..) |_, ix| out[ix] = ids[(ix + off) % ids.len]; return out; }
pub fn gapMs(rng: *std.Random.DefaultPrng, cfg: conf.Conf) u64 { const lo = @as(u64, cfg.acct_gap_secs[0]) * 1000; const hi = @as(u64, cfg.acct_gap_secs[1]) * 1000; if (hi <= lo) return lo; return rng.random().intRangeAtMost(u64, lo, hi); }
fn storOpen(env: *Env, id: []const u8) !data.Stor { const dir = try std.fs.path.join(env.aren, &.{ env.root, CF.sub, id, CF.stat }); try std.Io.Dir.cwd().createDirPath(env.iozz, dir); const path = try std.fs.path.joinZ(env.aren, &.{ dir, CF.dbfi }); return data.Stor.open(env.aren, path); }
pub fn kindOf(env: *Env, id: []const u8) Kind { var sto = storOpen(env, id) catch return .ok; defer sto.close(); const why = (sto.haltGet(env.aren) catch return .ok) orelse return .ok; if (std.mem.startsWith(u8, why, CF.owner1) or std.mem.startsWith(u8, why, CF.owner2)) return .owner; return .safety; }
pub fn migrate(aren: std.mem.Allocator, iozz: std.Io, root: []const u8) !bool { const dst = try std.fs.path.join(aren, &.{ root, CF.sub, "main" }); const cwd = std.Io.Dir.cwd(); if (cwd.access(iozz, dst, .{})) |_| { return false; } else |_| {} const old_stat = try std.fs.path.join(aren, &.{ root, CF.stat }); const old_prof = try std.fs.path.join(aren, &.{ root, CF.prof }); var moved = false; try cwd.createDirPath(iozz, dst); if (cwd.access(iozz, old_stat, .{})) |_| { try cwd.rename(old_stat, cwd, try std.fs.path.join(aren, &.{ dst, CF.stat }), iozz); moved = true; } else |_| {} if (cwd.access(iozz, old_prof, .{})) |_| { try cwd.rename(old_prof, cwd, try std.fs.path.join(aren, &.{ dst, CF.prof }), iozz); moved = true; } else |_| {} return moved; }
fn note(env: *Env, comptime fmtz: []const u8, args: anytype) void { const line = std.fmt.allocPrint(env.aren, fmtz, args) catch return; env.say(env.ctx, line); }
pub fn runAll(env: *Env) ![]const Res { var out: std.ArrayList(Res) = .empty; const seq = try order(env.aren, env.ids, env.now); var safety: u32 = 0; if (env.browser) { for (seq) |id| { if (kindOf(env, id) == .safety) safety += 1; } }
var stop_all = env.browser and safety >= CF.corr; if (stop_all) note(env, "{d} accounts are halted for safety: nothing runs until you check them and run: za resume --acct <id>", .{safety}); var ran: u32 = 0;
for (seq) |id| { if (env.browser) { if (stop_all or kindOf(env, id) != .ok) { try out.append(env.aren, .{ .id = id, .state = "rest", .code = 4 }); note(env, "account {s}: halted or resting, skipped", .{id}); continue; } if (ran > 0) { const gap = gapMs(env.rng, env.cfg); note(env, "waiting {d} s before the next account", .{gap / 1000}); env.nap(env.iozz, gap); } }
ran += 1; note(env, "== account {s} ==", .{id}); if (env.run(env.ctx, id)) |code| { try out.append(env.aren, .{ .id = id, .state = if (code == 0) "ok" else try std.fmt.allocPrint(env.aren, "exit {d}", .{code}), .code = code }); } else |err| { try out.append(env.aren, .{ .id = id, .state = @errorName(err), .code = erro.exitCode(err) }); }
if (env.browser and kindOf(env, id) == .safety) { safety += 1; if (safety >= CF.corr and !stop_all) { stop_all = true; note(env, "two accounts hit a safety stop: the remaining accounts do not run", .{}); } } }
return out.items; }
pub fn worst(res: []const Res) u8 { var code: u8 = 0; for (res) |rs| { if (rs.code > code) code = rs.code; } return code; }
